import{_ as n,o as e,c as a,a5 as c}from"./chunks/framework.CsGesDJn.js";const b=JSON.parse('{"title":"Nav theo role và các màn mobile bổ sung (2026-10-29)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/mobile-nav-role-parity/spec.md","filePath":"feature/mobile-nav-role-parity/spec.md"}'),h={name:"feature/mobile-nav-role-parity/spec.md"};function d(o,t,i,r,l,s){return e(),a("div",null,[...t[0]||(t[0]=[c('<h1 id="nav-theo-role-va-cac-man-mobile-bo-sung-2026-10-29" tabindex="-1">Nav theo role và các màn mobile bổ sung (2026-10-29) <a class="header-anchor" href="#nav-theo-role-va-cac-man-mobile-bo-sung-2026-10-29" aria-label="Permalink to &quot;Nav theo role và các màn mobile bổ sung (2026-10-29)&quot;">​</a></h1><p>&gt; Phạm vi: sidebar web, menu/drawer mobile và các màn mobile mới. Nguồn sự thật phân quyền trang là <a href="../../../../brandhub-web/src/routes/access.ts"><code>brandhub-web/src/routes/access.ts</code></a>; mobile phản chiếu trong <code>brandhub-mobile-app/src/utils/navAccess.ts</code>.</p><h2 id="_1-quy-tac" tabindex="-1">1. Quy tắc <a class="header-anchor" href="#_1-quy-tac" aria-label="Permalink to &quot;1. Quy tắc&quot;">​</a></h2><ul><li>Một trang chỉ hiện trong nav khi role hiện tại nằm trong quy tắc của route đó. Trang không có quy tắc thì mọi role đều thấy.</li><li>Trên mobile, ngoài việc ẩn mục menu còn <strong>bọc kiểm tra quyền ở cấp màn</strong> (<code>navigation/withAccess.tsx</code>): role không đủ quyền thấy &quot;Bạn không có quyền truy cập trang này.&quot;. Đây chỉ là lớp giao diện; backend vẫn là nơi quyết định quyền.</li><li>Mục &quot;Mẫu email&quot; của Agency (<code>/agency/:id/mail-templates</code>) hiện cho Owner agency và Manager của một Workspace thuộc Agency (cờ <code>agencyStaffOnly</code> trên web; mobile gọi API và chỉ hiện khi API trả danh sách).</li></ul><h2 id="_2-ma-tran-role-→-trang-workspace" tabindex="-1">2. Ma trận role → trang (workspace) <a class="header-anchor" href="#_2-ma-tran-role-→-trang-workspace" aria-label="Permalink to &quot;2. Ma trận role → trang (workspace)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trang</th><th>OWNER</th><th>MANAGER</th><th>CREATOR</th><th>CLIENT</th></tr></thead><tbody><tr><td>Lịch (Calendar), Chat</td><td>không</td><td>có</td><td>có</td><td>có</td></tr><tr><td>Yêu cầu nội dung</td><td>không</td><td>có</td><td>có</td><td>có</td></tr><tr><td>Chiến dịch, Gói dịch vụ, Mạng xã hội</td><td>có</td><td>có</td><td>không</td><td>có</td></tr><tr><td>Soạn thảo, Mẫu email, AI Studio</td><td>có</td><td>có</td><td>có</td><td>không</td></tr><tr><td>Xuất bản, Dashboard xuất bản</td><td>không</td><td>có</td><td>có</td><td>không</td></tr><tr><td>Thư viện</td><td>không</td><td>có</td><td>có</td><td>có</td></tr><tr><td>Khách hàng, Mời thành viên, Thành viên Workspace</td><td>có</td><td>có</td><td>không</td><td>không</td></tr></tbody></table><h2 id="_3-trang-web-đuoc-them-vao-nav" tabindex="-1">3. Trang web được thêm vào nav <a class="header-anchor" href="#_3-trang-web-đuoc-them-vao-nav" aria-label="Permalink to &quot;3. Trang web được thêm vào nav&quot;">​</a></h2><p>Xuất bản và Dashboard xuất bản (nhóm Tạo nội dung); Thống kê công ty và Mẫu email (nhóm Công ty, Agency); Cơ sở tri thức, Xu hướng, AI Video Studio (nhóm Danh sách); Lời mời (nhóm Lời mời); Lịch sử thanh toán và Mẫu Workspace (sidebar Admin).</p><h2 id="_4-man-mobile-đuoc-them" tabindex="-1">4. Màn mobile được thêm <a class="header-anchor" href="#_4-man-mobile-đuoc-them" aria-label="Permalink to &quot;4. Màn mobile được thêm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Màn</th><th>API</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Yêu cầu nội dung (danh sách, chi tiết, tạo/sửa)</td><td><code>/api/v1/workspaces/{id}/content-requests</code></td><td>Nút theo cờ <code>can*</code> do backend trả; ghi kèm <code>expectedVersion</code>; hạn nhập <code>DD/MM/YYYY HH:mm</code>, server kiểm khoảng hạn</td></tr><tr><td>Thống kê công ty</td><td><code>GET /api/v1/agencies/{id}/stats</code></td><td>Chỉ đọc, chỉ Owner agency; vẽ thanh ngang bằng View, không thêm thư viện biểu đồ</td></tr><tr><td>Dashboard xuất bản</td><td><code>GET /api/v1/workspaces/{id}/posts/dashboard</code></td><td>Chỉ đọc, KPI + theo nền tảng + bài gần đây, lọc theo trạng thái</td></tr><tr><td>Thư viện</td><td><code>GET /api/v1/workspaces/{id}/materials</code></td><td>Chỉ đọc, tìm theo tên, lọc Bản gốc/Đã chỉnh sửa/Đã đóng dấu</td></tr></tbody></table><p>Web: tab Media của Thư viện dùng kho tệp thật trên develop (cùng backend <code>/materials</code>).</p><h2 id="_5-gioi-han-đa-biet" tabindex="-1">5. Giới hạn đã biết <a class="header-anchor" href="#_5-gioi-han-đa-biet" aria-label="Permalink to &quot;5. Giới hạn đã biết&quot;">​</a></h2><ul><li><strong>Phân tích (Analytics)</strong> trên web vẫn là dữ liệu giả; backend không có nguồn số liệu tiếp cận/tương tác từ nền tảng mạng xã hội, nên chưa có API và chưa có màn mobile. Cần quyết định tích hợp insights của từng nền tảng trước.</li><li><strong>Trang Xuất bản chính</strong> (đăng bài) trên web vẫn dùng dữ liệu giả; mobile mới có Dashboard xuất bản. Backend đã có <code>submit</code>, <code>publish</code>, <code>reschedule</code>.</li><li><strong>Thư viện web</strong> (cập nhật 2026-10-29): develop đã có kho tệp thật (upload, thùng rác, khôi phục, tải xuống) do nhánh khác thực hiện; phần đọc danh sách tôi tự làm trước đó đã bị bỏ để dùng bản đó. Mobile mới chỉ đọc danh sách qua <code>GET /materials</code>.</li><li>Mobile chưa có màn Xuất bản (đăng bài), Phân tích, và các trang agency khác ngoài Thống kê (vai trò, tín dụng, gói dịch vụ agency).</li><li>Chưa có bằng chứng chạy thật trên trình duyệt/thiết bị; web không có testing-library/jsdom nên không có test component.</li></ul><h2 id="_6-kiem-thu" tabindex="-1">6. Kiểm thử <a class="header-anchor" href="#_6-kiem-thu" aria-label="Permalink to &quot;6. Kiểm thử&quot;">​</a></h2><p>Web vitest 70, mobile jest 140 (gồm test cho bảng quyền, <code>withAccess</code>, dịch vụ và tiện ích của các màn mới).</p>',15)])])}const u=n(h,[["render",d]]);export{b as __pageData,u as default};
